/**
 * cars.js — what a generated car drives like.
 *
 * Every car is generated by car_gen (see models.js). A BUILD is everything the
 * garage edits: the generator's parameter object plus paint, engine, drive and
 * gearbox choices. `deriveSpec` turns a build and the measured model into the
 * numbers the vehicle needs — mass from the body's volume, grip from the tyre
 * width, drag from the frontal area, CoM and travel from the stance — and
 * `buildCarParams` (unchanged physics) derives springs, dampers and bars.
 *
 * No three.js here: the probes import this headless.
 */

import { hashString, mulberry32 } from './util.js';

/** Static sag as a fraction of total suspension travel. */
const SAG_FRACTION = 0.28;
/** Body roll at the vehicle's own cornering limit, radians (~4.9 deg). */
const TARGET_ROLL = 0.085;
/** Damping as a fraction of critical, per direction. */
const ZETA_BUMP = 0.46;
const ZETA_REBOUND = 0.61;

/** car_gen's presets, as the garage names them. `null` style = free generation. */
export const BODY_STYLES = [
  { id: 'sedan',    name: 'Saloon',    blurb: 'Four doors, long wheelbase, settled at speed.' },
  { id: 'hatch',    name: 'Hatchback', blurb: 'Short, light and eager. Honest at the limit.' },
  { id: 'coupe',    name: 'Coupé',     blurb: 'Two doors, low roof, a little more grip.' },
  { id: 'supercar', name: 'Supercar',  blurb: 'Wide, low and planted. Loves a fast corner.' },
  { id: 'muscle',   name: 'Muscle',    blurb: 'Long bonnet, big torque, lazy steering.' },
  { id: 'wagon',    name: 'Estate',    blurb: 'A saloon with a long roof. Surprisingly quick.' },
  { id: 'suv',      name: 'SUV',       blurb: 'Tall and heavy; leans, then grips.' },
  { id: 'offroad',  name: 'Off-road',  blurb: 'Huge travel and four-wheel drive. Ignores ruts.' },
  { id: 'rally',    name: 'Rally',     blurb: 'Short, wide-tracked, all-wheel drive. Throw it.' },
  { id: 'wedge',    name: 'Wedge',     blurb: 'A doorstop with an engine. Pure downforce.' },
];

export function styleById(id) {
  return BODY_STYLES.find((s) => s.id === id) || null;
}

