/**
 * What real roads look like: mostly greyscale, then blue and red. Traffic
 * paints from this, weighted, so the road reads as a road and not a sweet jar.
 */
export const ROAD_PALETTE = [
  ['#e8e8e4', 20], ['#16171a', 18], ['#a3a8ae', 15], ['#5b6068', 12], ['#2350a8', 8],
  ['#1a2440', 6], ['#b3201c', 7], ['#7d1416', 3], ['#1f5a3a', 2], ['#c9b48c', 3],
  ['#d9701a', 1.5], ['#e2b419', 1], ['#1d6f78', 1.5], ['#9a5a36', 1], ['#5e2d82', 1],
];

export function roadColour(rng) {
  const total = ROAD_PALETTE.reduce((a, [, w]) => a + w, 0);
  let x = rng() * total;
  for (const [hex, w] of ROAD_PALETTE) if ((x -= w) <= 0) return hex;
  return ROAD_PALETTE[0][0];
}

