const SHIFT_MS = { dct: 45, manual: 150, auto: 185 };

/* ------------------------------------------------------------------ names -- */

const MAKES = ['Arden', 'Vanta', 'Strada', 'Koru', 'Meridian', 'Halcyon', 'Brio', 'Tessera', 'Volka',
  'Novak', 'Corsa', 'Ishida', 'Lumen', 'Orrin', 'Kestrel', 'Saber', 'Aurel', 'Monza'];
const MODELS = ['Vela', 'Strix', 'Onda', 'Rook', 'Kite', 'Talon', 'Mistral', 'Ember', 'Atlas', 'Nova',
  'Corvo', 'Riva', 'Sirocco', 'Pike', 'Lyra', 'Volta', 'Drift', 'Quill', 'Harrier', 'Sol'];
const TRIMS = { sport: ['GT', 'RS', 'S', 'R'], rugged: ['Trail', 'X', 'AT', '4x4'], plain: ['', 'SE', 'LX', 'Touring'] };

/** A make and model for a seed, and a trim that suits the shape. */
export function carName(seed, character = 'plain') {
  const rng = mulberry32(hashString(String(seed)) ^ 0x9e3779b9);
  const pick = (a) => a[Math.floor(rng() * a.length)];
  const trim = pick(TRIMS[character] || TRIMS.plain);
  return { make: pick(MAKES), model: pick(MODELS) + (trim ? ' ' + trim : '') };
}

/* ------------------------------------------------------------------ specs -- */

const clamp01 = (x) => Math.max(0, Math.min(1, x));
const clampR = (x, lo, hi) => Math.max(lo, Math.min(hi, x));

/** Geometry the spec reads, from the generator's parameters and the measured model. */
export function bodyShape(P, metrics) {
  const length = P.overhangF + P.wheelbase + P.overhangR;
  const height = metrics.bodyHeight;
  return {
    length,
    width: P.width,
    height,
    clearance: P.clearance,
    tyre: P.tireW,
    /** 0 = a box on wheels, 1 = a supercar: low, wide-tyred, flared. */
    sport: clamp01(clamp01((1.48 - height) / 0.36) * 0.55 + clamp01((P.tireW - 0.2) / 0.1) * 0.3 +
      clamp01((P.flare + P.flareR) / 0.15) * 0.15),
    rugged: clamp01((P.clearance - 0.16) / 0.12) * 0.6 + clamp01((P.wheelR - 0.34) / 0.08) * 0.4,
  };
}

export function characterOf(shape) {
  return shape.rugged > 0.45 ? 'rugged' : shape.sport > 0.6 ? 'sport' : 'plain';
}

/** What each style's factory fits: engines, drive (with odds of the alternative) and gearboxes. */
const STYLE_STOCK = {
  sedan:    { engines: ['i4', 'i5', 'i6', 'v6'], drive: ['rwd', 0.45, 'fwd'], gearbox: ['auto', 0.25, 'manual'] },
  hatch:    { engines: ['i3', 'i4', 'i4', 'boxer4', 'i5'], drive: ['fwd', 0.15, 'awd'], gearbox: ['manual', 0.4, 'auto'] },
  coupe:    { engines: ['i6', 'v6tt', 'flat6', 'rotary2', 'boxer4'], drive: ['rwd', 0.15, 'awd'], gearbox: ['manual', 0.5, 'dct'] },
  supercar: { engines: ['v8flat', 'v10', 'v12', 'v8tt'], drive: ['rwd', 0.35, 'awd'], gearbox: ['dct', 0, 'dct'] },
  muscle:   { engines: ['v8cross', 'v8cross', 'v8tt'], drive: ['rwd', 0, 'rwd'], gearbox: ['manual', 0.4, 'auto'] },
  wagon:    { engines: ['i5', 'i6', 'v6', 'i6diesel'], drive: ['awd', 0.4, 'rwd'], gearbox: ['auto', 0.2, 'manual'] },
  suv:      { engines: ['v6', 'i6', 'v8tt', 'i6diesel'], drive: ['awd', 0, 'awd'], gearbox: ['auto', 0, 'auto'] },
  offroad:  { engines: ['i6diesel', 'v8cross', 'i6'], drive: ['awd', 0, 'awd'], gearbox: ['manual', 0.5, 'auto'] },
  rally:    { engines: ['i4', 'i5', 'boxer4'], drive: ['awd', 0, 'awd'], gearbox: ['manual', 0, 'manual'] },
  wedge:    { engines: ['v8flat', 'v12', 'v10'], drive: ['rwd', 0, 'rwd'], gearbox: ['dct', 0, 'dct'] },
};

/** The style a free-generated car is closest to, from its shape. */
function styleFromShape(shape) {
  if (shape.rugged > 0.45) return shape.height > 1.8 ? 'offroad' : 'suv';
  if (shape.height > 1.62) return 'suv';
  if (shape.sport > 0.78) return 'supercar';
  if (shape.sport > 0.58) return 'coupe';
  if (shape.length < 4.15) return 'hatch';
  return 'sedan';
}

/** Short class label for the garage: the chosen style, else whichever the shape reads as. */
export function classLabel(shape, style = null) {
  const id = style || styleFromShape(shape);
  const names = { sedan: 'Saloon', hatch: 'Hatchback', coupe: 'Sports coupé', supercar: 'Supercar', muscle: 'Muscle car',
    wagon: 'Estate', suv: 'SUV', offroad: 'Off-roader', rally: 'Rally car', wedge: 'Wedge' };
  return names[id] || 'Car';
}

/** What the factory would fit. Deterministic in the seed, so a saved build keeps its engine. */
function stockChoices(shape, seed, style) {
  const rng = mulberry32(hashString(String(seed)) ^ 0x51ed270b);
  const S = STYLE_STOCK[style] || STYLE_STOCK[styleFromShape(shape)];
  const odds = ([a, p, b]) => (rng() < p ? b : a);
  return {
    engine: S.engines[Math.floor(rng() * S.engines.length)],
    drive: odds(S.drive),
    gearbox: odds(S.gearbox),
  };
}

/**
 * The vehicle spec for a build: the numbers `buildCarParams` and the
 * powertrain read. Choices left at `stock` come from the car's shape.
 */
export function deriveSpec(build, metrics) {
  const P = build.params;
  const shape = bodyShape(P, metrics);
  const stock = stockChoices(shape, build.seed ?? build.name ?? '', build.style);
  const choose = (v, s) => (!v || v === 'stock' ? s : v);
  const engine = choose(build.engine, stock.engine);
  const drive = choose(build.drive, stock.drive);
  const gearbox = choose(build.gearbox, stock.gearbox);

  // Mass: the body's bounding volume at ~108 kg/m³ is within 10 % of real cars
  // of every class here; big wheels and a rugged stance add the hardware.
  const volume = shape.length * shape.width * shape.height;
  const mass = clampR(108 * volume + (P.wheelR - 0.33) * 2200 + shape.rugged * 180, 880, 2700);

  // Frontal area × a drag coefficient from how boxy and tall it is, lumped as
  // force = k·v² the way vehicle.js wants it. Calibrated to the old roster.
  const area = shape.width * shape.height * 0.85;
  const cd = 0.3 + 0.03 * clampR(P.squareness - 3, 0, 6) + 0.1 * clamp01((shape.height - 1.2) / 0.6);
  const dragCoefficient = 0.6 * cd * area * 1.45;

  const kit = ((P.kitF > 0) + (P.kitR > 0)) * 0.25;
  // car_gen SPOILER_TYPES: None, Lip, Ducktail, Pedestal wing, GT wing, Roof spoiler
  const wing = [0, 0.1, 0.15, 0.35, 0.5, 0.1][P.spType | 0] * (P.spSize ?? 1);

  return {
    id: 'gen-' + (build.seed ?? 'custom'),
    name: build.name || 'Custom',
    engine,
    drive,
    gearbox,
    shiftTimeMs: SHIFT_MS[gearbox] || 160,
    mass: Math.round(mass),
    grip: clampR(1.2 + (P.tireW - 0.2) * 2.2 - 0.12 * clamp01((shape.height - 1.45) / 0.4) + kit * 0.1, 1.08, 1.48),
    comHeight: clampR(0.36 + 0.06 * clamp01((shape.height - 1.1) / 0.7) + 0.1 * (P.clearance - 0.1), 0.35, 0.46),
    travelScale: clampR(1 + (P.clearance - 0.1) * 3.5, 1, 1.6),
    dragCoefficient,
    // Capped at 0.85 g of extra load at 250 km/h: more compresses a low car onto its floor over crests.
    downforce: Math.min(clampR(3.6 - 3.2 * (shape.height - 1.1) / 0.6, 0.2, 3.4) + kit + wing, (0.85 * mass * 9.81) / (69.4 * 69.4)),
  };
}

/* --------------------------------------------------------------- physics -- */

/** Front/rear torque split for each layout, as [FL, FR, RL, RR] summing to 1. */
const DRIVE_SPLIT = {
  fwd: [0.5, 0.5, 0, 0],
  rwd: [0, 0, 0.5, 0.5],
  awd: [0.19, 0.19, 0.31, 0.31],
};

export function buildCarParams(spec, metrics, base, gravity) {
  const mass = spec.mass;

  // Travel follows wheel size — one number for all makes big wheels ride like a go-kart.
  const restLength = metrics.wheelRadius * 1.15 * (spec.travelScale || 1);

  // Static sag is the same fraction of travel for every car: k = m·g/(4·sag).
  const sag = restLength * SAG_FRACTION;
  const springK = (mass * gravity) / (4 * sag);

  // Critical damping for one corner is 2·sqrt(k · m/4) = sqrt(k·m).
  const cCrit = Math.sqrt(springK * mass);

  // Underbody clearance: enough to clear the suspension's own static travel.
  const clearance = Math.max(sag * 1.6, metrics.wheelRadius * 0.62);

  // SSF = half-track/CoM height; a vehicle rolls once lateral accel exceeds SSF·g.
  const comHeight = metrics.bodyHeight * spec.comHeight;
  const ssf = metrics.trackHalf / comHeight;
  const rolloverAccel = gravity * ssf * 0.82;

  // Bar sized from the roll moment the car sees; a fraction of spring rate fails big soft trucks.
  const aLimit = Math.min(spec.grip * gravity, rolloverAccel);
  const arm = Math.max(0.15, comHeight - base.frictionAnchorLift);
  const track = metrics.trackHalf * 2;
  const kRollNeeded = (mass * aLimit * arm) / TARGET_ROLL;
  const kRollSprings = (springK * track * track) / 2;
  const barTotal = Math.max(0, (kRollNeeded - kRollSprings) * restLength) / (track * track);

  // Generated bodies are not centred on the axle midpoint when the overhangs differ.
  const centreZ = metrics.bodyFrontZ != null ? (metrics.bodyFrontZ + metrics.bodyRearZ) / 2 : 0;

  return {
    ...base,
    ...spec,

    mass,
    wheelRadius: metrics.wheelRadius,
    wheelWidth: metrics.wheelWidth,
    trackHalf: metrics.trackHalf,
    wheelbaseHalf: metrics.wheelbaseHalf,
    /** Overall body height — the chase camera scales itself off this. */
    bodyHeight: metrics.bodyHeight,
    bodyHalfLength: metrics.bodyHalfLength,

    // The body's floor reaches the contact plane — collider must sit above real clearance or it scrapes.
    chassis: {
      hx: metrics.bodyHalfWidth * 0.92,
      hy: (metrics.bodyHeight - clearance) * 0.5,
      // Generated bodies taper in plan and section toward both ends; a box to the bumpers grounds the chin.
      hz: metrics.bodyHalfLength * 0.9,
    },
    chassisCentreY: clearance + (metrics.bodyHeight - clearance) * 0.5,
    chassisCentreZ: centreZ,
    groundClearance: clearance,
    comOffset: { x: 0, y: metrics.bodyHeight * spec.comHeight, z: 0.04 },

    // Anchor = hub − sag, so the settled pose matches the model's pose; omit sag and the car sits buried ~12 cm.
    anchorHeight: metrics.wheelRadius + restLength - sag,
    staticSag: sag,
    restLength,
    springK,
    damperBump: ZETA_BUMP * cCrit,
    damperRebound: ZETA_REBOUND * cCrit,
    maxSpringForce: mass * gravity * 3.0,
    antiRollFront: barTotal * 0.42,
    antiRollRear: barTotal * 0.58,

    driveBias: DRIVE_SPLIT[spec.drive] || DRIVE_SPLIT.awd,
    // Brake torque is sized against weight, not copied between vehicles.
    brakeForce: [
      mass * gravity * 0.3,
      mass * gravity * 0.3,
      mass * gravity * 0.2,
      mass * gravity * 0.2,
    ],
    handbrakeForce: mass * gravity * 0.36,
    rollingResistance: mass * 0.26,

    tyreFriction: spec.grip,
    /** Top-heavy vehicles run out of steering before they run out of roll — they push wide instead of tipping. */
    rolloverAccel,
    staticStabilityFactor: ssf,
    dragCoefficient: spec.dragCoefficient,
    downforce: spec.downforce,
  };
}
